INSERT INTO `ai_responses_cache` VALUES ('aa8c5597aecc8af9dc42b6ec306a80ee8abfe0c448c592587fb195e91140e87c','Hãy phân tích tin nhắn sau đây có chứa ngôn từ thô tục, xúc phạm, thù ghét hoặc không phù hợp với môi trường thư viện trường học không? \r\n        Chỉ trả về duy nhất từ \'SAFE\' nếu an toàn, hoặc \'UNSAFE\' nếu vi phạm. Tuyệt đối không giải thích gì thêm.\r\n        Tin nhắn: \"Hôm nay thư viện mở cửa mấy giờ ạ?\"','SAFE','2026-06-04 07:16:13'),('c03a8ab4c3c84ffd15eefafce523382682d26e489dfc1cd5ca753f572e648f44','Hãy phân tích tin nhắn sau đây có chứa ngôn từ thô tục, xúc phạm, thù ghét hoặc không phù hợp với môi trường thư viện trường học không? \r\n        Chỉ trả về duy nhất từ \'SAFE\' nếu an toàn, hoặc \'UNSAFE\' nếu vi phạm. Tuyệt đối không giải thích gì thêm.\r\n        Tin nhắn: \"Hello HDPE library from QA Test!\"','SAFE','2026-06-04 06:54:20');
/*!40000 ALTER TABLE `ai_responses_cache` ENABLE KEYS */;
