INSERT INTO `chat_logs` VALUES (1,1,'trong kho có bao nhiêu sách','Chào bạn! Hiện tại hệ thống thư viện HDPE đang cập nhật số lượng sách chính xác trong kho. \n\nBạn đang tìm kiếm tựa sách hoặc thể loại cụ thể nào không? Hãy chia sẻ để mình hỗ trợ kiểm tra và tìm kiếm giúp bạn nhé!','2026-05-27 00:11:26'),(2,1,'tô hoài có những tác phẩm nào','Chào bạn! Nhà văn Tô Hoài là một cây bút đại thụ của văn học Việt Nam với nhiều tác phẩm nổi tiếng. Các tác phẩm tiêu biểu nhất của ông gồm có:\n\n1. **Dế Mèn phiêu lưu ký** (Tác phẩm thiếu nhi kinh điển)\n2. **Vợ chồng A Phủ** (Truyện ngắn trong tập *Truyện Tây Bắc*)\n3. **Cát bụi chân ai** (Hồi ký)\n4. **O chuột** (Tập truyện về loài vật)\n\nBạn có thể tìm kiếm các tác phẩm này tại Thư viện HDPE ở quầy sách thuộc thể loại **Văn học trong nước**. Nếu cần tra cứu tình trạng còn/mất của sách trên kệ, bạn cứ báo cho tôi nhé!','2026-05-27 00:11:56');
/*!40000 ALTER TABLE `chat_logs` ENABLE KEYS */;
UNLOCK TABLES;

