INSERT INTO `ticket_messages` VALUES (11,11,19,'user','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','2026-05-08 18:38:41'),(12,11,1,'admin','Chào em, sách của em đã được gia hạn 1 lần trước đó rồi. Theo quy định, mỗi cuốn sách chỉ được gia hạn tối đa 1 lần. Em vui lòng mang sách đến trả đúng hạn nhé.','2026-05-08 19:14:53'),(13,11,19,'user','À ra vậy, em không để ý quy định này. Em sẽ mang trả sớm ạ.','2026-05-08 21:03:04'),(14,12,17,'user','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','2026-04-26 18:38:41'),(15,12,1,'admin','Chào em, sách của em đã được gia hạn 1 lần trước đó rồi. Theo quy định, mỗi cuốn sách chỉ được gia hạn tối đa 1 lần. Em vui lòng mang sách đến trả đúng hạn nhé.','2026-04-26 19:37:53'),(16,13,31,'user','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','2026-05-04 18:38:41'),(17,13,1,'admin','Chào em, sách của em đã được gia hạn 1 lần trước đó rồi. Theo quy định, mỗi cuốn sách chỉ được gia hạn tối đa 1 lần. Em vui lòng mang sách đến trả đúng hạn nhé.','2026-05-04 20:58:39'),(18,14,13,'user','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','2026-05-17 18:38:41'),(19,15,24,'user','Dạ, em vừa mượn cuốn \"Giải tích 1\" lúc sáng, nhưng mang về mở ra mới thấy trang 45 và 46 đã bị xé rách từ trước. Em báo lại để lúc trả không bị phạt ạ.','2026-05-23 18:38:41'),(20,15,1,'admin','Chào em, cảm ơn em đã báo cáo. Thư viện đã ghi nhận tình trạng sách rách trang 45,46 của cuốn \"Giải tích 1\" em đang mượn. Em cứ yên tâm sử dụng nhé, sẽ không có hình phạt nào khi em trả sách.','2026-05-23 20:31:27'),(21,16,16,'user','Thư viện mình có cho phép sinh viên đề xuất mua sách chuyên ngành không ạ? Khoa em có mấy cuốn tham khảo tiếng Anh rất hay nhưng thư viện chưa có.','2026-05-15 18:38:41'),(22,16,1,'admin','Chào em, thư viện luôn hoan nghênh các đề xuất từ sinh viên. Em có thể gửi danh sách tên sách, tác giả và nhà xuất bản qua form \"Đề xuất sách\" hoặc gửi trực tiếp email này nhé.','2026-05-15 20:02:11'),(23,16,16,'user','Dạ em sẽ tổng hợp gửi email cho thư viện. Em cảm ơn!','2026-05-15 20:51:06'),(24,17,35,'user','Em có một cuốn sách sắp đến hạn trả, nhưng khi lên hệ thống OPAC để gia hạn thì nút gia hạn bị mờ không bấm được. Nhờ thư viện kiểm tra giúp em tài khoản này ạ.','2026-05-16 18:38:41'),(25,17,1,'admin','Chào em, sách của em đã được gia hạn 1 lần trước đó rồi. Theo quy định, mỗi cuốn sách chỉ được gia hạn tối đa 1 lần. Em vui lòng mang sách đến trả đúng hạn nhé.','2026-05-16 22:17:05'),(26,17,35,'user','À ra vậy, em không để ý quy định này. Em sẽ mang trả sớm ạ.','2026-05-17 00:03:44'),(27,18,25,'user','Dạ, em vừa mượn cuốn \"Giải tích 1\" lúc sáng, nhưng mang về mở ra mới thấy trang 45 và 46 đã bị xé rách từ trước. Em báo lại để lúc trả không bị phạt ạ.','2026-04-25 18:38:41'),(28,18,1,'admin','Chào em, cảm ơn em đã báo cáo. Thư viện đã ghi nhận tình trạng sách rách trang 45,46 của cuốn \"Giải tích 1\" em đang mượn. Em cứ yên tâm sử dụng nhé, sẽ không có hình phạt nào khi em trả sách.','2026-04-25 21:36:07'),(29,19,5,'user','Dạ admin ơi, tự nhiên tài khoản của em bị báo là Khóa mượn sách. Em đã trả hết sách rồi mà ạ?','2026-05-14 18:38:41'),(30,19,1,'admin','Chào em, hệ thống ghi nhận em đã trả sách cuốn \"Đắc Nhân Tâm\" trễ hẹn 5 ngày vào tuần trước nên tài khoản bị tạm khóa 7 ngày. Đến thứ Hai tuần sau tài khoản sẽ tự động mở lại nhé.','2026-05-14 21:01:12'),(31,20,31,'user','Dạ thưa thầy/cô, hôm qua em có làm rơi ví và mất luôn thẻ thư viện. Cho em hỏi thủ tục làm lại thẻ cần những gì ạ?','2026-05-14 18:38:41'),(32,20,1,'admin','Chào em, để làm lại thẻ em mang thẻ sinh viên và CMND/CCCD đến quầy hỗ trợ tại tầng 1 vào giờ hành chính nhé. Phí cấp lại thẻ là 50.000đ.','2026-05-14 20:39:55'),(33,20,31,'user','Dạ vâng, em cảm ơn thầy/cô ạ. Chiều nay em sẽ qua làm lại.','2026-05-14 21:27:51'),(34,21,38,'user','Dạ, em vừa mượn cuốn \"Giải tích 1\" lúc sáng, nhưng mang về mở ra mới thấy trang 45 và 46 đã bị xé rách từ trước. Em báo lại để lúc trả không bị phạt ạ.','2026-05-09 18:38:41'),(35,21,1,'admin','Chào em, cảm ơn em đã báo cáo. Thư viện đã ghi nhận tình trạng sách rách trang 45,46 của cuốn \"Giải tích 1\" em đang mượn. Em cứ yên tâm sử dụng nhé, sẽ không có hình phạt nào khi em trả sách.','2026-05-09 21:58:41'),(36,22,21,'user','Dạ thưa thầy/cô, hôm qua em có làm rơi ví và mất luôn thẻ thư viện. Cho em hỏi thủ tục làm lại thẻ cần những gì ạ?','2026-05-03 18:38:41'),(37,22,1,'admin','Chào em, để làm lại thẻ em mang thẻ sinh viên và CMND/CCCD đến quầy hỗ trợ tại tầng 1 vào giờ hành chính nhé. Phí cấp lại thẻ là 50.000đ.','2026-05-03 21:52:38'),(38,22,21,'user','Dạ vâng, em cảm ơn thầy/cô ạ. Chiều nay em sẽ qua làm lại.','2026-05-03 22:36:21'),(39,23,32,'user','Dạ thưa thầy/cô, hôm qua em có làm rơi ví và mất luôn thẻ thư viện. Cho em hỏi thủ tục làm lại thẻ cần những gì ạ?','2026-05-18 18:38:41'),(40,23,1,'admin','Chào em, để làm lại thẻ em mang thẻ sinh viên và CMND/CCCD đến quầy hỗ trợ tại tầng 1 vào giờ hành chính nhé. Phí cấp lại thẻ là 50.000đ.','2026-05-18 20:54:35'),(41,23,32,'user','Dạ vâng, em cảm ơn thầy/cô ạ. Chiều nay em sẽ qua làm lại.','2026-05-18 22:47:48'),(42,24,31,'user','Dạ thưa thầy/cô, hôm qua em có làm rơi ví và mất luôn thẻ thư viện. Cho em hỏi thủ tục làm lại thẻ cần những gì ạ?','2026-05-20 18:38:42'),(43,24,1,'admin','Chào em, để làm lại thẻ em mang thẻ sinh viên và CMND/CCCD đến quầy hỗ trợ tại tầng 1 vào giờ hành chính nhé. Phí cấp lại thẻ là 50.000đ.','2026-05-20 19:54:21'),(44,24,31,'user','Dạ vâng, em cảm ơn thầy/cô ạ. Chiều nay em sẽ qua làm lại.','2026-05-20 21:35:31'),(45,25,11,'user','Dạ